const projectRecipients = `-- name: ProjectRecipients :many
SELECT pm.account_id
FROM project_member AS pm
JOIN project AS p ON p.id = pm.project_id
JOIN organization_membership AS om ON om.organization_id = p.organization_id AND om.account_id = pm.account_id
JOIN account AS a ON a.id = pm.account_id AND a.active
LEFT JOIN external_project_policy AS ep ON ep.project_id = p.id
WHERE pm.project_id = $1
  AND ($2::text = ''
       OR om.membership_kind = 'internal'
       OR $2::text = ANY (COALESCE(ep.permissions, ARRAY[]::text[])))
ORDER BY pm.account_id
`

type ProjectRecipientsParams struct {
	ProjectID  pgtype.UUID
	Permission string
}

func (q *Queries) ProjectRecipients(ctx context.Context, arg ProjectRecipientsParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, projectRecipients, arg.ProjectID, arg.Permission)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var account_id pgtype.UUID
		if err := rows.Scan(&account_id); err != nil {
			return nil, err
		}
		items = append(items, account_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

